/* Generated by `xxd -i -l 23712 abmf.crx`, with variable names edited. */
#include "bin/abmf00glp_crx.h"

/* Tests based on ABMF00GLP_R_20201890000_01D_30S_MO.crx, comparing
 * decompressed values against the uncompressed .rnx reference.
 */
void test_abmf00glp_crx(void)
{
    struct rinex_stream *crx;
    struct rinex_parser *p;
    const char *msg;
    rinex_error_t err;
    unsigned int ofs, ii;

    /* 8 tests: open and verify header */
    p = NULL;
    crx = rinex_buffer_stream(abmf_crx, abmf_crx_len);
    msg = rinex_open(&p, crx);
    ok(msg == NULL, "rinex_open() for CRX succeeded");
    if (!p) BAIL_OUT();
    ok(p->n_obs['G' & 31] == 18, "18 observables for GPS");
    ok(p->n_obs['E' & 31] == 20, "20 observables for Galileo");
    ok(p->n_obs['S' & 31] == 8, "8 observables for SBAS");
    ok(p->n_obs['R' & 31] == 20, "20 observables for GLONASS");
    ok(p->n_obs['C' & 31] == 12, "12 observables for BeiDou");
    ok(p->n_obs['J' & 31] == 12, "12 observables for QZSS");
    ok(p->n_obs['I' & 31] == 4, "4 observables for NavIC");

    /* 10 tests: first epoch metadata */
    err = p->read(p);
    ok(err == RINEX_SUCCESS, "CRX read() #1 succeeded");
    ok(p->epoch.yyyy_mm_dd == 20200707, "date is 2020-07-07");
    ok(p->epoch.hh_mm == 0, "time-of-day is 00:00");
    ok(p->epoch.flag == '0', "epoch flag is 0");
    ok(p->epoch.sec_e7 == 0, "seconds is 0.0000000");
    ok(p->epoch.n_sats == 42, "first epoch has 42 satellites");
    ok(p->epoch.clock_offset == 0, "clock offset is 0");
    ok(p->sats[0].system == 'E' && p->sats[0].number == 4, "first sat is E04");
    ok(p->sats[1].system == 'G' && p->sats[1].number == 15, "second sat is G15");
    ok(p->sats[41].system == 'C' && p->sats[41].number == 22, "last sat is C22");

    /* 23 tests: first satellite (E04) observations — same as rinex_v3 test */
    ofs = p->sats[0].obs_0;
    ok(p->obs[ofs+0] == 28541439844, "E04 obs 1 is 28541439.844");
    ok(p->lli[ofs+0] == ' ', "E04 first LLI is blank");
    ok(p->ssi[ofs+0] == '5', "E04 first SSI is 5");
    ok(p->obs[ofs+1] == 149986288817, "E04 obs 2 is 149986288.817");
    ok(p->lli[ofs+1] == '0', "E04 second LLI is 0");
    ok(p->obs[ofs+2] == 1175101, "E04 obs 3 is 1175.101");
    ok(p->obs[ofs+3] == 35700, "E04 obs 4 is 35.700");
    ok(p->obs[ofs+4] == 28541441120, "E04 obs 5 is 28541441.120");
    ok(p->obs[ofs+5] == 121742127938, "E04 obs 6 is 121742127.938");
    ok(p->obs[ofs+6] == 953962, "E04 obs 7 is 953.962");
    ok(p->obs[ofs+7] == 40164, "E04 obs 8 is 40.164");
    ok(p->obs[ofs+8] == 28541441048, "E04 obs 9 is 28541441.048");
    ok(p->obs[ofs+9] == 112002756211, "E04 obs 10 is 112002756.211");
    ok(p->obs[ofs+10] == 877350, "E04 obs 11 is 877.350");
    ok(p->obs[ofs+11] == 39658, "E04 obs 12 is 39.658");
    ok(p->obs[ofs+12] == 28541440314, "E04 obs 13 is 28541440.314");
    ok(p->obs[ofs+13] == 114924561309, "E04 obs 14 is 114924561.309");
    ok(p->obs[ofs+14] == 900319, "E04 obs 15 is 900.319");
    ok(p->obs[ofs+15] == 40849, "E04 obs 16 is 40.849");
    ok(p->obs[ofs+16] == 28541440985, "E04 obs 17 is 28541440.985");
    ok(p->obs[ofs+17] == 113463662329, "E04 obs 18 is 113463662.329");
    ok(p->obs[ofs+18] == 888852, "E04 obs 19 is 888.852");
    ok(p->obs[ofs+19] == 43227, "E04 obs 20 is 43.227");

    /* 18 tests: second satellite (G15) observations */
    ofs = p->sats[1].obs_0;
    ok(p->obs[ofs+0] == 21062787884, "G15 obs 1 is 21062787.884");
    ok(p->obs[ofs+1] == 110685754321, "G15 obs 2 is 110685754.321");
    ok(p->obs[ofs+2] == -1567275, "G15 obs 3 is -1567.275");
    ok(p->obs[ofs+3] == 48530, "G15 obs 4 is 48.530");
    ok(p->obs[ofs+4] == 21062787634, "G15 obs 5 is 21062787.634");
    ok(p->obs[ofs+5] == 50327, "G15 obs 6 is 50.327");
    ok(p->obs[ofs+6] == 21062785399, "G15 obs 7 is 21062785.399");
    ok(p->obs[ofs+7] == 86248658482, "G15 obs 8 is 86248658.482");
    ok(p->obs[ofs+8] == -1221255, "G15 obs 9 is -1221.255");
    ok(p->obs[ofs+9] == 50327, "G15 obs 10 is 50.327");
    ok(p->obs[ofs+10] == 21062786045, "G15 obs 11 is 21062786.045");
    ok(p->obs[ofs+11] == 86248665487, "G15 obs 12 is 86248665.487");
    ok(p->obs[ofs+12] == -1221317, "G15 obs 13 is -1221.317");
    ok(p->obs[ofs+13] == 44877, "G15 obs 14 is 44.877");
    for (ii = 14; ii < 18; ++ii)
        ok(p->obs[ofs+ii] == INT64_MIN, "G15 obs N is blank");

    /* 11 tests: second epoch (delta-decompressed) */
    err = p->read(p);
    ok(err == RINEX_SUCCESS, "CRX read() #2 succeeded");
    ok(p->epoch.yyyy_mm_dd == 20200707, "epoch 2 date is 2020-07-07");
    ok(p->epoch.sec_e7 == 300000000, "epoch 2 seconds is 30.0000000");
    ok(p->epoch.n_sats == 42, "epoch 2 has 42 satellites");
    ofs = p->sats[0].obs_0;
    ok(p->obs[ofs+0] == 28534747227, "E04 epoch2 obs 1 is 28534747.227");
    ok(p->obs[ofs+1] == 149951119017, "E04 epoch2 obs 2 is 149951119.017");
    ok(p->obs[ofs+2] == 1170082, "E04 epoch2 obs 3 is 1170.082");
    ok(p->obs[ofs+3] == 34638, "E04 epoch2 obs 4 is 34.638");
    ok(p->ssi[ofs+0] == '5', "E04 epoch2 SSI is 5");
    ok(p->lli[ofs+0] == ' ', "E04 epoch2 LLI is blank");
    ok(p->sats[0].system == 'E' && p->sats[0].number == 4, "epoch2 first sat is E04");

    /* 3 tests: third epoch (00:01:00.0) */
    err = p->read(p);
    ok(err == RINEX_SUCCESS, "CRX read() #3 succeeded");
    ok(p->epoch.n_sats == 42, "epoch 3 has 42 satellites");
    ok(p->epoch.hh_mm == 1, "epoch 3 time is 00:01");

    p->destroy(p);
    crx->destroy(crx);
}

/* A CRX v3 file with one satellite per epoch, whose epoch lines are
 * therefore short enough to be mistaken for RINEX 3 epoch lines with a
 * clock offset (previously "failed to parse clock offset: G01").  The
 * receiver clock offset lines (made by hand, since RNX2CRX 4.2.0 crashes
 * on clock offsets) include a 3 ms jump, so the differences do not fit
 * in 32 bits.  CRX2RNX decodes it to clock offsets of 0.000123456789,
 * 0.003123456789 and 0.003123458023 s.
 */
static const char one_sat_crx[] =
    "3.0                 COMPACT RINEX FORMAT                    CRINEX VERS   / TYPE\n"
    "RNX2CRX ver.4.2.0                       10-Oct-26 01:10     CRINEX PROG / DATE\n"
    "     3.04           OBSERVATION DATA    G                   RINEX VERSION / TYPE\n"
    "test                                                        PGM / RUN BY / DATE\n"
    "G    2 C1C L1C                                              SYS / # / OBS TYPES\n"
    "                                                            END OF HEADER\n"
    "> 2020 07 07 00 00  0.0000000  0  1      G01\n"
    "3&123456789\n"
    "3&20000000000 3&105000000000 &717\n"
    "                   3\n"
    "3000000000\n"
    "30000 30000\n"
    "                 1 &\n"
    "-2999998766\n"
    "0 0\n";

/** Return a malloc'd copy of \a text with the first \a from replaced by
 * \a to, padded for use as a stream buffer.
 */
static char *replace_once(const char *text, const char *from, const char *to)
{
    const char *pos = strstr(text, from);
    size_t len = strlen(text) - strlen(from) + strlen(to);
    char *res;

    if (!pos)
        BAIL_OUT("fixture does not contain \"%s\"", from);
    res = calloc(1, len + 81);
    sprintf(res, "%.*s%s%s", (int)(pos - text), text, to, pos + strlen(from));
    return res;
}

/** Read up to three epochs of the CRX text \a text (padded).  Returns
 * how many epochs were read; *\a p_err gets the status of the read that
 * stopped, and \a errmsg its message.
 */
static int read_crx(const char *text, int64_t clocks[3], int64_t c1c[3],
    rinex_error_t *p_err, char errmsg[160])
{
    struct rinex_stream *stream;
    struct rinex_parser *p = NULL;
    int n_read = 0;

    stream = rinex_buffer_stream(text, (int)strlen(text));
    if (rinex_open(&p, stream))
        BAIL_OUT("rinex_open() failed for a CRX variant");
    while (n_read < 3 && (*p_err = p->read(p)) == RINEX_SUCCESS)
    {
        clocks[n_read] = p->epoch.clock_offset;
        c1c[n_read] = p->n_obs['G' & 31] > 0 && p->epoch.n_sats == 1
            ? p->obs[0] : -1;
        ++n_read;
    }
    if (n_read == 3)
        *p_err = p->read(p);
    strcpy(errmsg, p->errmsg);
    p->destroy(p);
    stream->destroy(stream);
    return n_read;
}

void test_one_sat_crx(void)
{
    static const int64_t clocks[3] = { 123456789LL, 3123456789LL, 3123458023LL };
    static const struct
    {
        const char *name, *from, *to, *error;
        int n_good;
    } bad[] = {
        { "clock arc order 6", "3&123456789\n", "6&123456789\n",
          "bad arc initialization", 0 },
        { "non-numeric clock", "3&123456789\n", "3&x\n",
          "bad arc initialization", 0 },
        { "clock continuation without initialization", "3&123456789\n",
          "1234\n", "without initialization", 0 },
        { "text after clock", "3&123456789\n", "3&123456789 x\n",
          "unexpected text", 0 },
        { "clock overflow", "3&123456789\n", "3&99999999999999999999\n",
          "bad arc initialization", 0 },
        { "observation arc order 6", "3&20000000000 ", "6&20000000000 ",
          "bad arc initialization", 0 },
        { "non-numeric arc order", "3&20000000000 ", "x&20000000000 ",
          "bad arc initialization", 0 },
        /* Overflows need a second epoch, so the first one is read. */
        { "observation value overflow", "\n30000 30000\n",
          "\n9223372036000000000 30000\n", "arc value overflows", 1 },
        { "clock value overflow", "\n3000000000\n",
          "\n9223372036854775000\n", "arc value overflows", 1 },
        { "difference overflow", "\n-2999998766\n",
          "\n9223372036000000000\n", "arc value overflows", 2 },
    };
    int64_t got_clocks[3], got_c1c[3];
    char errmsg[160], *text;
    rinex_error_t err;
    int ii, n_read;

    /* Order-3 arcs, with a 3 ms clock jump. */
    text = replace_once(one_sat_crx, "", "");
    n_read = read_crx(text, got_clocks, got_c1c, &err, errmsg);
    ok(n_read == 3 && err == RINEX_EOF
        && !memcmp(got_clocks, clocks, sizeof clocks)
        && got_c1c[0] == 20000000000LL && got_c1c[2] == 20000060000LL,
        "one-satellite CRX: epochs, observations and clock offsets (%s)",
        errmsg);
    free(text);

    /* Order-0 arcs hold absolute values, for the clock and C1C. */
    {
        char *t1 = replace_once(one_sat_crx, "3&123456789\n", "0&123456789\n");
        char *t2 = replace_once(t1, "\n3000000000\n", "\n3123456789\n");
        char *t3 = replace_once(t2, "\n-2999998766\n", "\n3123458023\n");
        char *t4 = replace_once(t3, "3&20000000000 ", "0&20000000000 ");
        char *t5 = replace_once(t4, "\n30000 30000\n", "\n20000030000 30000\n");
        text = replace_once(t5, "\n0 0\n", "\n20000060000 0\n");
        free(t1);
        free(t2);
        free(t3);
        free(t4);
        free(t5);
    }
    n_read = read_crx(text, got_clocks, got_c1c, &err, errmsg);
    ok(n_read == 3 && err == RINEX_EOF
        && !memcmp(got_clocks, clocks, sizeof clocks)
        && got_c1c[0] == 20000000000LL && got_c1c[1] == 20000030000LL
        && got_c1c[2] == 20000060000LL,
        "one-satellite CRX: order-0 arcs are absolute (%s)", errmsg);
    free(text);

    /* Malformed arcs are rejected without corrupting state. */
    for (ii = 0; ii < (int)(sizeof bad / sizeof bad[0]); ++ii)
    {
        text = replace_once(one_sat_crx, bad[ii].from, bad[ii].to);
        n_read = read_crx(text, got_clocks, got_c1c, &err, errmsg);
        ok(n_read == bad[ii].n_good && err == RINEX_ERR_BAD_FORMAT
            && strstr(errmsg, bad[ii].error) != NULL,
            "one-satellite CRX: %s is rejected (%s)", bad[ii].name, errmsg);
        free(text);
    }
}

/* A CRX v3 file (from RNX2CRX 4.2.0) whose satellite list shrinks from
 * G01 G02 to G01, keeps G01 through a delta line that only changes the
 * time (shorter than the epoch line it updates), then grows to G01 G02
 * G03.
 */
static const char sat_list_crx[] =
    "3.0                 COMPACT RINEX FORMAT                    CRINEX VERS   / TYPE\n"
    "RNX2CRX ver.4.2.0                       17-Oct-26 14:54     CRINEX PROG / DATE\n"
    "     3.04           OBSERVATION DATA    G                   RINEX VERSION / TYPE\n"
    "test                                                        PGM / RUN BY / DATE\n"
    "G    2 C1C L1C                                              SYS / # / OBS TYPES\n"
    "                                                            END OF HEADER\n"
    "> 2020 07 07 00 00  0.0000000  0  2      G01G02\n"
    "\n"
    "3&20000000000 3&105000000000 &7&7\n"
    "3&21000000000 3&110000000000 &7&7\n"
    "                   3              1         &&&\n"
    "\n"
    "30000 150000\n"
    "                 1 &\n"
    "\n"
    "0 0\n"
    "                   3              3         G02G03\n"
    "\n"
    "0 0\n"
    "3&21000090000 3&110000450000 &7&7\n"
    "3&22000090000 3&115000450000 &7&7\n";

void test_sat_list_crx(void)
{
    static const struct
    {
        int hh_mm, sec, n_sats;
        int64_t c1c[3];
    } want[] = {
        { 0, 0, 2, { 20000000000LL, 21000000000LL } },
        { 0, 30, 1, { 20000030000LL } },
        { 1, 0, 1, { 20000060000LL } },
        { 1, 30, 3, { 20000090000LL, 21000090000LL, 22000090000LL } },
    };
    struct rinex_stream *stream;
    struct rinex_parser *p = NULL;
    rinex_error_t err;
    char *text;
    int ii, jj, good;

    text = replace_once(sat_list_crx, "", "");
    stream = rinex_buffer_stream(text, (int)strlen(text));
    if (rinex_open(&p, stream))
        BAIL_OUT("rinex_open() failed for sat_list_crx");
    for (ii = 0; ii < (int)(sizeof want / sizeof want[0]); ++ii)
    {
        err = p->read(p);
        good = err == RINEX_SUCCESS && p->epoch.hh_mm == want[ii].hh_mm
            && p->epoch.sec_e7 == want[ii].sec * 10000000
            && p->epoch.n_sats == want[ii].n_sats;
        for (jj = 0; good && jj < want[ii].n_sats; ++jj)
        {
            good = p->sats[jj].system == 'G' && p->sats[jj].number == jj + 1
                && p->obs[p->sats[jj].obs_0] == want[ii].c1c[jj];
        }
        ok(good, "satellite-list CRX: epoch %d (%s)", ii + 1, p->errmsg);
    }
    ok(p->read(p) == RINEX_EOF, "satellite-list CRX: then EOF");
    p->destroy(p);
    stream->destroy(stream);
    free(text);
}

/* A CRX v3 file like RNX2CRX 4.2.0 writes for 60 satellites (G01-G32,
 * E01-E28) and then 61 (adding E29), so the epoch line is longer than
 * the parser's initial 200-byte copy of it, and then grows.  The parser
 * once left the grown copy without a NUL, so it read past the end.
 */
void test_long_epoch_crx(void)
{
    static const char header[] =
        "3.0                 COMPACT RINEX FORMAT                    CRINEX VERS   / TYPE\n"
        "RNX2CRX ver.4.2.0                       17-Oct-26 14:57     CRINEX PROG / DATE\n"
        "     3.04           OBSERVATION DATA    M                   RINEX VERSION / TYPE\n"
        "test                                                        PGM / RUN BY / DATE\n"
        "G    1 C1C                                                  SYS / # / OBS TYPES\n"
        "E    1 C1C                                                  SYS / # / OBS TYPES\n"
        "                                                            END OF HEADER\n"
        "> 2020 07 07 00 00  0.0000000  0 60      ";
    struct rinex_stream *stream;
    struct rinex_parser *p = NULL;
    rinex_error_t err;
    char *text, *pos;
    int ii;

    text = calloc(1, 8192);
    pos = text + sprintf(text, "%s", header);
    for (ii = 0; ii < 60; ++ii)
        pos += sprintf(pos, "%c%02d", ii < 32 ? 'G' : 'E', ii < 32 ? ii + 1 : ii - 31);
    pos += sprintf(pos, "\n\n");
    for (ii = 0; ii < 60; ++ii)
        pos += sprintf(pos, "3&%lld &&\n", 20000000000LL + 1000000LL * ii);
    pos += sprintf(pos, "%19s3%14s1%186sE29\n\n", "", "", "");
    for (ii = 0; ii < 60; ++ii)
        pos += sprintf(pos, "30000\n");
    sprintf(pos, "3&20060030000 &&\n");

    stream = rinex_buffer_stream(text, (int)strlen(text));
    if (rinex_open(&p, stream))
        BAIL_OUT("rinex_open() failed for the long epoch line CRX");
    err = p->read(p);
    if (err == RINEX_SUCCESS)
        err = p->read(p);
    ok(err == RINEX_SUCCESS && p->epoch.n_sats == 61
        && p->sats[60].system == 'E' && p->sats[60].number == 29
        && p->obs[p->sats[60].obs_0] == 20060030000LL,
        "long epoch line CRX: 61 satellites in epoch 2 (%s)", p->errmsg);
    ok(p->read(p) == RINEX_EOF, "long epoch line CRX: then EOF");
    p->destroy(p);
    stream->destroy(stream);
    free(text);
}

int main(int argc, char *argv[])
{
    plan(92);

    test_abmf00glp_crx();
    test_one_sat_crx();
    test_sat_list_crx();
    test_long_epoch_crx();

    done_testing(); (void)argc; (void)argv;
}
